package com.automationstudio.engine.karate.worker;
import java.util.*;import java.util.concurrent.ConcurrentLinkedQueue;import java.util.concurrent.atomic.AtomicInteger;
public final class SequentialProbe{private static final AtomicInteger ACTIVE=new AtomicInteger(),MAX=new AtomicInteger();private static final Queue<String> COMPLETED=new ConcurrentLinkedQueue<>();public static void run(){run("",75);}public static void run(String identity,int delay){int active=ACTIVE.incrementAndGet();MAX.accumulateAndGet(active,Math::max);try{Thread.sleep(delay);COMPLETED.add(identity);}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{ACTIVE.decrementAndGet();}}static void reset(){ACTIVE.set(0);MAX.set(0);COMPLETED.clear();}static int maximum(){return MAX.get();}static List<String> completed(){return List.copyOf(COMPLETED);}private SequentialProbe(){}}
